<script setup lang="ts">
import { computed, ref, shallowRef, watch } from 'vue';
import { DialogRoot, DialogPortal, DialogOverlay, DialogContent, DialogTitle, DialogDescription, DialogClose } from 'reka-ui';
import { X } from 'lucide-vue-next';
import type { ActionKind, Host, Repository, TagDetail, StashDetail, Containment, VerificationResult, Remote, AppSettings, GitAction, ReviewSession } from '../shared/protocol';
import { errorMessage } from '../lib/format';
import { useLocale } from '../lib/vue-locale';
import { Requests } from '../lib/state';
import { buildPullRequestUrl } from '../lib/providers';
const props = defineProps<{ open:boolean; host:Host; repo:Repository|null; generation:number; kind:'tag'|'stash'|'containment'|'remotes'|'archive'|'pull-request'|'reviews'|'diagnostics'; target?:string; settings:AppSettings; remotes:Remote[]; reviews?:ReviewSession[] }>();
const emit = defineEmits<{ 'update:open':[value:boolean]; action:[kind:ActionKind,initial:Partial<GitAction>]; select:[oid:string]; resumeReview:[review:ReviewSession]; error:[error:unknown] }>();
const { text } = useLocale();
const loading=ref(false),error=ref(''),output=ref('');
const tag=shallowRef<TagDetail|null>(null),stash=shallowRef<StashDetail|null>(null),containment=shallowRef<Containment|null>(null),verification=shallowRef<VerificationResult|null>(null);
const formTarget=ref(''),format=ref<'zip'|'tar'>('zip'),prefix=ref(''),remote=ref(''),source=ref(''),target=ref('main');
const requests=new Requests(id=>props.host.cancel(id));let epoch=0;
const title=computed(()=>({tag:text('标签详情','Tag details'),stash:text('储藏详情','Stash details'),containment:text('包含此提交的引用','References containing this commit'),remotes:text('远程仓库','Remotes'),archive:text('导出仓库归档','Export repository archive'),'pull-request':text('创建合并请求链接','Create pull request link'),reviews:text('评审会话','Review sessions'),diagnostics:text('诊断','Diagnostics')})[props.kind]);
function valid(id:string,generation:number,version:number){return props.open&&epoch===version&&props.repo?.id===id&&props.generation===generation;}
async function load(){const version=++epoch;requests.cancelAll();tag.value=null;stash.value=null;containment.value=null;verification.value=null;output.value='';error.value='';formTarget.value=props.target??props.repo?.head??'HEAD';source.value=props.repo?.branch??'';remote.value=props.remotes[0]?.name??'';const repo=props.repo;if(!props.open)return; if(props.kind==='diagnostics'){loading.value=true;try{output.value=JSON.stringify(await props.host.diagnostics(),null,2);}catch(e){if(version===epoch)error.value=errorMessage(e);}finally{if(version===epoch)loading.value=false;}return;}if(!repo)return;const generation=props.generation,request=requests.begin('metadata');loading.value=true;try{if(props.kind==='tag'){const result=await props.host.tagDetail(repo.id,props.target??'',request.id);if(valid(repo.id,generation,version))tag.value=result;}else if(props.kind==='stash'){const result=await props.host.stashDetail(repo.id,props.target??'',request.id);if(valid(repo.id,generation,version))stash.value=result;}else if(props.kind==='containment'){const result=await props.host.containment(repo.id,props.target??repo.head??'',request.id);if(valid(repo.id,generation,version))containment.value=result;}}catch(e){if(valid(repo.id,generation,version))error.value=errorMessage(e);}finally{request.finish();if(version===epoch)loading.value=false;}}
watch([()=>props.open,()=>props.kind,()=>props.target,()=>props.repo?.id,()=>props.generation],()=>{if(props.open)void load();else{epoch++;requests.cancelAll();}});
async function verify(){const repo=props.repo,item=tag.value;if(!repo||!item||!repo.trusted||loading.value)return;const version=epoch,generation=props.generation,request=requests.begin('verify');loading.value=true;try{const result=await props.host.verify({repoId:repo.id,requestId:request.id,kind:'tag',target:item.ref});if(valid(repo.id,generation,version))verification.value=result;}catch(e){if(valid(repo.id,generation,version))error.value=errorMessage(e);}finally{request.finish();if(version===epoch)loading.value=false;}}
async function exportArchive(){const repo=props.repo;if(!repo||!repo.trusted||loading.value)return;const version=epoch,generation=props.generation,request=requests.begin('archive');loading.value=true;try{const saved=await props.host.archive({repoId:repo.id,requestId:request.id,target:formTarget.value,format:format.value,prefix:prefix.value||undefined});if(valid(repo.id,generation,version))output.value=saved?text('归档已保存。','Archive saved.'):text('已取消保存，未导出归档。','Save cancelled. No archive exported.');}catch(e){if(valid(repo.id,generation,version))error.value=errorMessage(e);}finally{request.finish();if(version===epoch)loading.value=false;}}
async function openPullRequest(){const selected=props.remotes.find(item=>item.name===remote.value);const url=selected?buildPullRequestUrl(selected.fetchUrl,source.value,target.value,undefined,props.settings.pullRequestProviders):null;if(!url){error.value=text('无法为此远程和分支生成安全链接。','Cannot build a safe link for this remote and branch.');return;}try{await props.host.openUrl(url);}catch(e){error.value=errorMessage(e);}}
function action(kind:ActionKind,initial:Partial<GitAction>){emit('update:open',false);emit('action',kind,initial);}
function select(oid:string){emit('update:open',false);emit('select',oid);}
</script>
<template><DialogRoot :open="open" @update:open="value=>emit('update:open',value)"><DialogPortal><DialogOverlay class="native-dialog-overlay"/><DialogContent class="native-dialog">
<header class="metadata-header"><DialogTitle>{{ title }}</DialogTitle><DialogClose class="wb-icon" :aria-label="text('关闭','Close')"><X :size="16"/></DialogClose></header><DialogDescription>{{ repo?.name ?? 'QGitGraph' }} · {{ text('来自当前原生宿主的真实数据','Actual data from the native host') }}</DialogDescription>
<p v-if="loading" role="status">{{ text('正在读取…','Loading…') }}</p><p v-if="error" role="alert" class="error">{{ error }}</p>
<template v-if="tag"><dl><dt>{{ text('名称','Name') }}</dt><dd>{{ tag.name }}</dd><dt>OID</dt><dd class="mono">{{ tag.oid }}</dd><dt>{{ text('目标','Target') }}</dt><dd class="mono">{{ tag.targetOid }}</dd><dt>{{ text('类型','Type') }}</dt><dd>{{ tag.annotated?text('附注标签','Annotated'):text('轻量标签','Lightweight') }}</dd><dt>{{ text('创建者','Tagger') }}</dt><dd>{{ tag.tagger }} &lt;{{ tag.email }}&gt;</dd><dt>{{ text('签名','Signature') }}</dt><dd>{{ tag.signature.status }} · {{ tag.signature.signer }}</dd></dl><pre>{{ tag.message }}</pre><div class="metadata-actions"><button class="wb-button" @click="select(tag.targetOid)">{{ text('定位提交','Reveal commit') }}</button><button class="wb-button" :disabled="loading||!repo?.trusted" @click="verify">{{ text('验证签名','Verify signature') }}</button><button class="wb-button" @click="action('tag-push',{target:tag.name})">{{ text('推送标签…','Push tag…') }}</button><button class="wb-button" @click="action('tag-delete',{target:tag.name})">{{ text('删除标签…','Delete tag…') }}</button></div></template>
<template v-if="verification"><pre>{{ verification.status }} · {{ verification.signer }} · {{ verification.key }}
{{ verification.output }}</pre></template>
<template v-if="stash"><dl><dt>{{ text('条目','Entry') }}</dt><dd>{{ stash.selector }}</dd><dt>OID</dt><dd class="mono">{{ stash.oid }}</dd><dt>{{ text('基准','Base') }}</dt><dd class="mono">{{ stash.base }}</dd><dt>INDEX</dt><dd class="mono">{{ stash.index }}</dd></dl><pre>{{ stash.message }}</pre><div class="metadata-actions"><button class="wb-button" @click="select(stash.oid)">{{ text('查看文件与差异','View files and diff') }}</button><button class="wb-button" @click="action('stash-apply',{target:stash.selector})">{{ text('应用…','Apply…') }}</button><button class="wb-button" @click="action('stash-pop',{target:stash.selector})">{{ text('弹出…','Pop…') }}</button><button class="wb-button" @click="action('stash-branch',{target:stash.selector})">{{ text('创建分支…','Create branch…') }}</button><button class="wb-button" @click="action('stash-drop',{target:stash.selector})">{{ text('删除…','Drop…') }}</button></div></template>
<div v-if="containment" class="tool-list"><code>{{ containment.oid }}</code><p>HEAD: {{ containment.head }}</p><div v-for="item in containment.refs" :key="item.fullName"><span>{{ item.name }}</span><code>{{ item.oid.slice(0,10) }}</code></div></div>
<div v-if="kind==='remotes'" class="tool-list"><div v-for="item in remotes" :key="item.name"><strong>{{ item.name }}</strong><code>{{ item.fetchUrl }}</code><code v-if="item.pushUrl!==item.fetchUrl">{{ item.pushUrl }}</code><button class="wb-button" @click="action('fetch',{remote:item.name})">Fetch</button><button class="wb-button" @click="action('remote-edit',{remote:item.name,url:item.fetchUrl})">{{ text('编辑…','Edit…') }}</button><button class="wb-button" @click="action('remote-remove',{remote:item.name})">{{ text('移除…','Remove…') }}</button></div><button class="wb-button" @click="action('remote-add',{})">{{ text('添加远程…','Add remote…') }}</button></div>
<form v-if="kind==='archive'" class="metadata-form" @submit.prevent="exportArchive"><label>{{ text('目标引用／提交','Target ref / commit') }}<input v-model="formTarget" required :disabled="loading"/></label><label>{{ text('格式','Format') }}<select v-model="format"><option>zip</option><option>tar</option></select></label><label>{{ text('路径前缀（可选）','Path prefix (optional)') }}<input v-model="prefix" :disabled="loading"/></label><p v-if="!repo?.trusted">{{ text('导出前需明确信任此仓库。','Trust this repository before exporting.') }}</p><button class="wb-button" :disabled="loading||!repo?.trusted">{{ text('选择保存位置…','Choose destination…') }}</button></form>
<form v-if="kind==='pull-request'" class="metadata-form" @submit.prevent="openPullRequest"><p>{{ text('只在浏览器打开创建页，不调用平台 API，不会自动创建合并请求。','Opens a creation page in your browser. No provider API request or automatic pull request creation.') }}</p><label>Remote<select v-model="remote"><option v-for="item in remotes" :key="item.name">{{ item.name }}</option></select></label><label>{{ text('源分支','Source branch') }}<input v-model="source" required/></label><label>{{ text('目标分支','Target branch') }}<input v-model="target" required/></label><button class="wb-button">{{ text('打开创建页','Open creation page') }}</button></form>
<div v-if="kind==='reviews'" class="tool-list"><p v-if="!reviews?.length">{{ text('当前仓库没有保存的评审会话。','No saved review sessions for this repository.') }}</p><div v-for="review in reviews" :key="review.key"><code>{{ review.selection?.oid ?? review.selection?.target }}</code><span>{{ review.paths.length }} {{ text('个已读文件','reviewed files') }}</span><button class="wb-button" @click="emit('update:open',false);emit('resumeReview',review)">{{ text('恢复评审','Resume review') }}</button></div></div>
<pre v-if="output">{{ output }}</pre>
</DialogContent></DialogPortal></DialogRoot></template>
<style scoped>.metadata-header{display:flex;align-items:center;justify-content:space-between;gap:10px}.metadata-actions{display:flex;flex-wrap:wrap;gap:7px}.metadata-form{display:flex;flex-direction:column;gap:12px}dl{display:grid;grid-template-columns:75px minmax(0,1fr);gap:6px 10px;font-size:11px}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}code{overflow-wrap:anywhere}</style>
